package com.opensocket.aievent.core.integration.identity;
import java.time.OffsetDateTime; import java.util.*; import java.util.concurrent.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository;
@Repository @Profile("!prod") @ConditionalOnProperty(prefix="integration-identity",name="store",havingValue="MEMORY")
public class InMemoryIntegrationWebhookEndpointRepository implements IntegrationWebhookEndpointRepository {
 private final Map<String,IntegrationWebhookEndpoint> values=new ConcurrentHashMap<>(); private final Map<String,OffsetDateTime> nonces=new ConcurrentHashMap<>();
 public IntegrationWebhookEndpoint save(IntegrationWebhookEndpoint v){String key=v.tenantId()+"|"+v.endpointId();values.compute(key,(k,old)->{if(old!=null){if(!old.endpointTokenHash().equals(v.endpointTokenHash())||!old.connectionId().equals(v.connectionId())||!old.principalId().equals(v.principalId())||old.providerType()!=v.providerType())throw new IllegalStateException("WEBHOOK_ENDPOINT_IDENTITY_IMMUTABLE");if(v.version()!=old.version()+1)throw new IllegalStateException("WEBHOOK_ENDPOINT_VERSION_CONFLICT");}else if(v.version()!=1)throw new IllegalStateException("WEBHOOK_ENDPOINT_VERSION_CONFLICT");return v;});return v;} public Optional<IntegrationWebhookEndpoint> find(String t,String id){return Optional.ofNullable(values.get(t+"|"+id));} public Optional<IntegrationWebhookEndpoint> findByTokenHash(String h){return values.values().stream().filter(v->v.endpointTokenHash().equals(h)).findFirst();} public List<IntegrationWebhookEndpoint> list(String t,String c,int n){return values.values().stream().filter(v->v.tenantId().equals(t)&&(c==null||c.isBlank()||v.connectionId().equals(c))).sorted(Comparator.comparing(IntegrationWebhookEndpoint::endpointId)).limit(Math.max(1,n)).toList();}
 public boolean reserveNonce(String t,String c,String e,String h,OffsetDateTime x,String corr){String k=t+"|"+c+"|"+h;return nonces.putIfAbsent(k,x)==null;} public int deleteExpiredNonces(OffsetDateTime before,int limit){int count=0;for(var entry:nonces.entrySet()){if(count>=limit)break;if(entry.getValue().isBefore(before)&&nonces.remove(entry.getKey(),entry.getValue()))count++;}return count;} public String mode(){return "MEMORY";}
}
